const wheelchairPrescriptionMarkup = "<form autocomplete=\"off\" class=\"main-panel\" id=\"wcForm\">\n<section class=\"card section\" id=\"section1\">\n<div class=\"section-header\">\n<h2>Section 1: Client profile, medical background and goals</h2>\n<p>Captures the reason for referral, person-context and clinical risks that must shape any equipment direction.</p>\n<button class=\"section-toggle\" onclick=\"toggleSection('section1', this)\" type=\"button\">Minimise</button></div>\n<div class=\"section-body\">\n<div class=\"grid\">\n<label class=\"field span-4\">Client name<input id=\"clientName\" type=\"text\"/></label>\n<label class=\"field span-4\">Date of assessment<input id=\"assessmentDate\" type=\"date\"/></label>\n<label class=\"field span-2\">DOB<input id=\"dob\" type=\"date\"/></label>\n<label class=\"field span-2\">Weight kg<input id=\"weight\" min=\"0\" step=\"0.1\" type=\"number\"/></label>\n<label class=\"field span-6\">Primary diagnosis<input id=\"primaryDx\" type=\"text\"/></label>\n<label class=\"field span-6\">Other relevant diagnosis<input id=\"otherDx\" type=\"text\"/></label>\n<label class=\"field span-4\">Funding body / pathway<input id=\"fundingBody\" placeholder=\"public program, insurance, hospital, private, other\" type=\"text\"/></label>\n<label class=\"field span-8\">Reason for referral<input id=\"reasonReferral\" placeholder=\"New prescription, replacement, review, pressure/posture concern, discharge planning\" type=\"text\"/></label>\n<label class=\"field span-12\">Mobility and seating related goals<textarea id=\"mobilityGoals\" placeholder=\"What must the wheelchair enable? Include home, community, care, work/education, transport and discharge goals.\"></textarea></label>\n</div>\n<div class=\"subhead\">Client context</div>\n<div class=\"grid compact\">\n<label class=\"field span-4\">Productivity roles<input id=\"productivity\" placeholder=\"work / volunteering / education / caring\" type=\"text\"/></label>\n<label class=\"field span-4\">Recreation and community interests<input id=\"recreation\" type=\"text\"/></label>\n<label class=\"field span-4\">Carer comments<input id=\"carerComments\" type=\"text\"/></label>\n<div class=\"span-4\"><strong>Remoteness</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"remoteness\" type=\"radio\" value=\"Metropolitan\"/> Metropolitan</label><label class=\"radio\"><input name=\"remoteness\" type=\"radio\" value=\"Regional\"/> Regional</label><label class=\"radio\"><input name=\"remoteness\" type=\"radio\" value=\"Rural\"/> Rural</label><label class=\"radio\"><input name=\"remoteness\" type=\"radio\" value=\"Remote\"/> Remote</label><label class=\"radio\"><input name=\"remoteness\" type=\"radio\" value=\"Very remote\"/> Very remote</label></div></div>\n<div class=\"span-4\"><strong>Amount of time in wheelchair</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"wcTime\" type=\"radio\" value=\"Community access only\"/> Community access only</label><label class=\"radio\"><input name=\"wcTime\" type=\"radio\" value=\"Outdoor home access only\"/> Outdoor home access only</label><label class=\"radio\"><input name=\"wcTime\" type=\"radio\" value=\"Indoor transit only\"/> Indoor transit only</label><label class=\"radio\"><input name=\"wcTime\" type=\"radio\" value=\"Full-time use\"/> Full-time use</label></div></div>\n<div class=\"span-4\"><strong>Carer/s</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"carers\" type=\"checkbox\" value=\"None\"/> None</label><label class=\"check\"><input name=\"carers\" type=\"checkbox\" value=\"Informal\"/> Informal</label><label class=\"check\"><input name=\"carers\" type=\"checkbox\" value=\"Formal\"/> Formal</label></div></div>\n</div>\n<div class=\"subhead\">Medical background</div>\n<div class=\"grid compact\">\n<div class=\"span-4\"><strong>Cause</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"cause\" type=\"radio\" value=\"Injury\"/> Injury</label><label class=\"radio\"><input name=\"cause\" type=\"radio\" value=\"Health condition\"/> Health condition</label><label class=\"radio\"><input name=\"cause\" type=\"radio\" value=\"Other\"/> Other</label></div></div>\n<div class=\"span-4\"><strong>Impairment</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"impairment\" type=\"checkbox\" value=\"Physical\"/> Physical</label><label class=\"check\"><input name=\"impairment\" type=\"checkbox\" value=\"Neurological\"/> Neurological</label><label class=\"check\"><input name=\"impairment\" type=\"checkbox\" value=\"Cognitive\"/> Cognitive</label><label class=\"check\"><input name=\"impairment\" type=\"checkbox\" value=\"Psychosomatic\"/> Psychosomatic</label><label class=\"check\"><input name=\"impairment\" type=\"checkbox\" value=\"Sensory\"/> Sensory</label></div></div>\n<div class=\"span-4\"><strong>Condition</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"conditionStatus\" type=\"radio\" value=\"Stable\"/> Stable</label><label class=\"radio\"><input name=\"conditionStatus\" type=\"radio\" value=\"Deteriorating\"/> Deteriorating</label><label class=\"radio\"><input name=\"conditionStatus\" type=\"radio\" value=\"Fluctuating\"/> Fluctuating</label></div></div>\n<label class=\"field span-6\">History / onset<textarea id=\"historyOnset\"></textarea></label>\n<label class=\"field span-6\">Medication / precautions / other related assessments<textarea id=\"medicalPrecautions\" placeholder=\"Include hip precautions, epilepsy, pain, home mods, FIM/FCA, gait/transfer assessment, behavioural support etc.\"></textarea></label>\n</div>\n<div class=\"subhead\">Pressure injury history and skin risk</div>\n<div class=\"grid compact\">\n<div class=\"span-3\"><strong>History of pressure injury</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"historyPI\" type=\"radio\" value=\"Yes\"/> Yes</label><label class=\"radio\"><input name=\"historyPI\" type=\"radio\" value=\"No\"/> No</label></div></div>\n<div class=\"span-3\"><strong>Sensation</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"sensation\" type=\"radio\" value=\"Intact\"/> Intact</label><label class=\"radio\"><input name=\"sensation\" type=\"radio\" value=\"Impaired\"/> Impaired</label><label class=\"radio\"><input name=\"sensation\" type=\"radio\" value=\"Absent\"/> Absent</label></div></div>\n<div class=\"span-3\"><strong>Current pressure injury</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"currentPI\" type=\"radio\" value=\"Yes\"/> Yes</label><label class=\"radio\"><input name=\"currentPI\" type=\"radio\" value=\"No\"/> No</label></div></div>\n<div class=\"span-3\"><strong>Requires wound care referral</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"woundReferral\" type=\"radio\" value=\"Yes\"/> Yes</label><label class=\"radio\"><input name=\"woundReferral\" type=\"radio\" value=\"No\"/> No</label></div></div>\n<label class=\"field span-3\">PI stage / staged by<input id=\"piStage\" type=\"text\"/></label>\n<label class=\"field span-3\">Location<input id=\"piLocation\" type=\"text\"/></label>\n<label class=\"field span-3\">Seating related?<select id=\"seatingRelated\"><option></option><option>Yes</option><option>No</option><option>Unknown</option></select></label>\n<label class=\"field span-3\">Risk factors related to seating?<select id=\"seatingRiskFactors\"><option></option><option>Yes</option><option>No</option><option>Unknown</option></select></label>\n<label class=\"field span-12\">Current management strategies and AT<textarea id=\"pressureManagement\" placeholder=\"Cushion, repositioning routine, wound plan, skin checks, hoist/transfer approach, tilt/recline use, bed surfaces.\"></textarea></label>\n<div class=\"span-12 pressure-actions\">\n<label class=\"check bariatric-flag\"><input id=\"bariatricFlag\" name=\"bariatricFlag\" onchange=\"toggleBariatricPanel()\" type=\"checkbox\" value=\"Bariatric flag\"/> Flag bariatric considerations</label>\n</div>\n<div class=\"span-12 conditional-panel\" hidden=\"\" id=\"bariatricPanel\">\n<div class=\"subhead inline-subhead\">Bariatric features</div>\n<div class=\"grid compact\" style=\"margin-top:12px;\">\n<div class=\"span-12\"><strong>Bariatric features</strong><div class=\"check-grid\"><label class=\"check\"><input name=\"bariatricFeatures\" type=\"checkbox\" value=\"Apple ascites\"/> Apple ascites</label><label class=\"check\"><input name=\"bariatricFeatures\" type=\"checkbox\" value=\"Apple pannus\"/> Apple pannus</label><label class=\"check\"><input name=\"bariatricFeatures\" type=\"checkbox\" value=\"Pear abduction\"/> Pear abduction</label><label class=\"check\"><input name=\"bariatricFeatures\" type=\"checkbox\" value=\"Pear adduction\"/> Pear adduction</label><label class=\"check\"><input name=\"bariatricFeatures\" type=\"checkbox\" value=\"Gluteal shelf\"/> Gluteal shelf</label></div></div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"card section\" id=\"section2\">\n<div class=\"section-header\">\n<h2>Section 2: Proposed-position measurements and current seating/mobility base</h2>\n<p>Measurements are placed first so the supplier-ready output starts with what suppliers most need to size and shortlist trial equipment.</p>\n<button class=\"section-toggle\" onclick=\"toggleSection('section2', this)\" type=\"button\">Minimise</button></div>\n<div class=\"section-body\">\n<div class=\"subhead\">Client measurements in proposed position</div>\n<div class=\"measurement-layout\">\n<div>\n<table class=\"measurement-table\">\n<thead><tr><th>Measurement</th><th>Left / value mm</th><th>Right mm</th></tr></thead>\n<tbody>\n<tr><td><span class=\"measure-label\"><span class=\"measure-code\">A</span><span class=\"measure-desc\">Buttock/thigh depth</span></span></td><td><input id=\"measA_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measA_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">B</span><span class=\"measure-desc\">Lower leg length</span></span></td><td><input id=\"measB_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measB_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">C</span><span class=\"measure-desc\">Foot length</span></span></td><td><input id=\"measC_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measC_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">D</span><span class=\"measure-desc\">Ischial well length</span></span></td><td><input id=\"measD_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measD_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">E</span><span class=\"measure-desc\">Seat to elbow</span></span></td><td><input id=\"measE_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measE_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">F</span><span class=\"measure-desc\">PSIS</span></span></td><td><input id=\"measF_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measF_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">G</span><span class=\"measure-desc\">Inferior scapula</span></span></td><td><input id=\"measG_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measG_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">H</span><span class=\"measure-desc\">Axilla</span></span></td><td><input id=\"measH_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measH_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">I</span><span class=\"measure-desc\">Top of shoulder</span></span></td><td><input id=\"measI_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measI_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">J</span><span class=\"measure-desc\">Top of head</span></span></td><td><input id=\"measJ_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measJ_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">K</span><span class=\"measure-desc\">Shoulder width</span></span></td><td><input id=\"measK_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measK_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">L</span><span class=\"measure-desc\">Chest width</span></span></td><td><input id=\"measL_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measL_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">M</span><span class=\"measure-desc\">Hip width</span></span></td><td><input id=\"measM_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measM_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">N</span><span class=\"measure-desc\">External knee width</span></span></td><td><input id=\"measN_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measN_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">O</span><span class=\"measure-desc\">Internal knee width</span></span></td><td><input id=\"measO_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measO_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr><tr><td><span class=\"measure-label\"><span class=\"measure-code\">P</span><span class=\"measure-desc\">External ankle/foot at widest point</span></span></td><td><input id=\"measP_L\" min=\"0\" step=\"1\" type=\"number\"/></td><td><input id=\"measP_R\" min=\"0\" step=\"1\" type=\"number\"/></td></tr>\n</tbody>\n</table>\n<label class=\"field\" style=\"margin-top:10px;\">Overall width / asymmetrical width notes<textarea id=\"overallWidthNotes\" placeholder=\"Include windswept legs, scoliosis, thigh position, abducted/adducted posture, pannus/gluteal shelf implications.\"></textarea></label>\n</div>\n<div class=\"measurement-side\">\n<div class=\"visual-card body-chart-card\"><img alt=\"Body landmark reference chart for A-P seating measurements\" class=\"body-chart-img\" src=\"/assets/wheelchair-prescription/body-landmark-reference.png\"/><div class=\"visual-caption\">Body landmark reference for A-P measurements. Use the proposed seated posture for dimensions and document accommodated overall width where posture or tissue shape changes fit.</div></div>\n<div class=\"note\">Use the proposed seated posture for measurements before sending through seat width, seat depth, back height and support requirements. If posture is asymmetrical, document the accommodated overall width in the notes.</div>\n</div>\n</div>\n<div class=\"subhead\">Current seating base</div>\n<div class=\"grid compact\">\n<div class=\"span-3\"><strong>Seating base</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"seatingBase\" type=\"radio\" value=\"Manual\"/> Manual</label><label class=\"radio\"><input name=\"seatingBase\" type=\"radio\" value=\"Power\"/> Power</label></div></div>\n<label class=\"field span-5\">Current manufacturer/model<input id=\"currentModel\" type=\"text\"/></label>\n<label class=\"field span-2\">Age of base<input id=\"baseAge\" type=\"text\"/></label>\n<label class=\"field span-2\">Condition<input id=\"baseCondition\" type=\"text\"/></label>\n<div class=\"span-3\"><strong>Current wheelchair base</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"currentBaseMeets\" type=\"radio\" value=\"Meets needs\"/> Meets needs</label><label class=\"radio\"><input name=\"currentBaseMeets\" type=\"radio\" value=\"No longer meets needs\"/> No longer meets needs</label></div></div>\n<label class=\"field span-9\">Client comments about current base<textarea id=\"currentBaseComments\"></textarea></label>\n</div>\n<div class=\"subhead\">Current seating and mobility base - manual</div>\n<div class=\"selection-cards\">\n<div class=\"selection-card\"><h4>Folding manual</h4><img alt=\"Folding manual wheelchair\" src=\"/assets/wheelchair-prescription/folding-manual-wheelchair.jpg\"/><label class=\"radio\"><input name=\"manualCurrentType\" type=\"checkbox\" value=\"Folding\"/> Select folding manual</label><div class=\"card-caption\">Useful when transport/storage and simpler handling are priorities.</div></div>\n<div class=\"selection-card\"><h4>Rigid manual</h4><img alt=\"Rigid manual wheelchair\" src=\"/assets/wheelchair-prescription/rigid-manual-wheelchair.jpg\"/><label class=\"radio\"><input name=\"manualCurrentType\" type=\"checkbox\" value=\"Rigid\"/> Select rigid manual</label><div class=\"card-caption\">Useful when propulsion efficiency, performance and reduced flex are priorities.</div></div>\n<div class=\"selection-card\"><h4>Tilt in space</h4><img alt=\"Tilt in space manual wheelchair\" src=\"/assets/wheelchair-prescription/tilt-in-space-manual-wheelchair.jpg\"/><label class=\"radio\"><input name=\"manualCurrentType\" type=\"checkbox\" value=\"Tilt in space\"/> Select tilt in space</label><div class=\"card-caption\">Useful when posture support, pressure management and caregiver handling are priorities.</div></div>\n</div>\n<div class=\"manual-propulsion-layout\" style=\"margin-top:14px;\">\n<div class=\"option-panel propulsion-panel\">\n<strong>Propulsion</strong>\n<div class=\"check-grid\">\n<label class=\"radio\"><input name=\"propulsion\" type=\"radio\" value=\"Independent full-time\"/> Independent full-time</label>\n<label class=\"radio\"><input name=\"propulsion\" type=\"radio\" value=\"Independent part-time\"/> Independent part-time</label>\n<label class=\"radio\"><input name=\"propulsion\" type=\"radio\" value=\"Requires assistance\"/> Requires assistance</label>\n<label class=\"radio\"><input name=\"propulsion\" type=\"radio\" value=\"Dependent\"/> Dependent</label>\n</div>\n</div>\n<div class=\"option-panel power-addon-panel\">\n<strong>Power add-on</strong>\n<div class=\"check-grid\">\n<label class=\"check\"><input name=\"powerAddon\" type=\"checkbox\" value=\"Front attached\"/> Front attached</label>\n<label class=\"check\"><input name=\"powerAddon\" type=\"checkbox\" value=\"Push-rim activated\"/> Push-rim activated</label>\n<label class=\"check\"><input name=\"powerAddon\" type=\"checkbox\" value=\"SmartDrive\"/> SmartDrive</label>\n<label class=\"check\"><input name=\"powerAddon\" type=\"checkbox\" value=\"Other\"/> Other</label>\n</div>\n<label class=\"field manual-power-notes\">Power add-on notes<input id=\"powerAddonOther\" placeholder=\"Model, mounting, setup, transport, charging or handling considerations\" type=\"text\"/></label>\n</div>\n</div>\n<div class=\"subhead\">Current seating and mobility base - power</div>\n<div class=\"selection-cards\">\n<div class=\"selection-card\"><h4>Front wheel drive</h4><img alt=\"Front wheel drive power wheelchair\" src=\"/assets/wheelchair-prescription/front-wheel-drive-power-wheelchair.jpg\"/><label class=\"radio\"><input name=\"driveConfig\" type=\"radio\" value=\"Front wheel drive\"/> Select front wheel drive</label><div class=\"card-caption\">Often prioritised where climbing obstacles and more direct obstacle approach are important.</div></div>\n<div class=\"selection-card\"><h4>Mid wheel drive</h4><img alt=\"Mid wheel drive power wheelchair\" src=\"/assets/wheelchair-prescription/mid-wheel-drive-power-wheelchair.jpg\"/><label class=\"radio\"><input name=\"driveConfig\" type=\"radio\" value=\"Mid wheel drive\"/> Select mid wheel drive</label><div class=\"card-caption\">Often prioritised for tighter indoor turning and central drive feel.</div></div>\n<div class=\"selection-card\"><h4>Rear wheel drive</h4><img alt=\"Rear wheel drive power wheelchair\" src=\"/assets/wheelchair-prescription/rear-wheel-drive-power-wheelchair.jpg\"/><label class=\"radio\"><input name=\"driveConfig\" type=\"radio\" value=\"Rear wheel drive\"/> Select rear wheel drive</label><div class=\"card-caption\">Often prioritised for directional stability and outdoor tracking.</div></div>\n</div>\n<div class=\"grid compact\" style=\"margin-top:14px;\">\n<label class=\"field span-3\">Current seat width mm<input id=\"currentSeatWidth\" min=\"0\" step=\"1\" type=\"number\"/></label>\n<label class=\"field span-3\">Current seat depth mm<input id=\"currentSeatDepth\" min=\"0\" step=\"1\" type=\"number\"/></label>\n<div class=\"span-6\"><strong>Current seat functions</strong><div class=\"check-grid four\"><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Tilt\"/> Tilt</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Recline - power\"/> Recline - power</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Recline - manual\"/> Recline - manual</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Elevating leg rests - power\"/> Elevating leg rests - power</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Elevating leg rests - manual\"/> Elevating leg rests - manual</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Seat elevate\"/> Seat elevate</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Anterior tilt\"/> Anterior tilt</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Active reach\"/> Active reach</label><label class=\"check\"><input name=\"currentSeatFunctions\" type=\"checkbox\" value=\"Stand\"/> Stand</label></div></div>\n</div>\n<div class=\"subhead\">Current seating system and accessories</div>\n<div class=\"grid compact\">\n<label class=\"field span-3\">Cushion<input id=\"currentCushion\" type=\"text\"/></label>\n<label class=\"field span-2\">Cushion size<input id=\"currentCushionSize\" type=\"text\"/></label>\n<label class=\"field span-3\">Cushion meets needs?<select id=\"currentCushionMeets\"><option></option><option>Meets needs</option><option>Does not meet needs</option><option>Unknown</option></select></label>\n<label class=\"field span-4\">Cushion notes<input id=\"currentCushionNotes\" type=\"text\"/></label>\n<label class=\"field span-3\">Backrest<input id=\"currentBackrest\" type=\"text\"/></label>\n<label class=\"field span-2\">Backrest size<input id=\"currentBackrestSize\" type=\"text\"/></label>\n<label class=\"field span-3\">Backrest hardware<select id=\"backrestHardware\"><option></option><option>Removable</option><option>Fixed</option><option>Integrated</option></select></label>\n<label class=\"field span-4\">Backrest meets needs?<select id=\"currentBackrestMeets\"><option></option><option>Meets needs</option><option>Does not meet needs</option><option>Unknown</option></select></label>\n<div class=\"span-12\"><strong>Current accessories</strong><div class=\"check-grid four\"><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Headrest\"/> Headrest</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Laterals\"/> Laterals</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Postural hip belt\"/> Postural hip belt</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Shoulder harness\"/> Shoulder harness</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Ankle huggers\"/> Ankle huggers</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Foot cups\"/> Foot cups</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Tray\"/> Tray</label><label class=\"check\"><input name=\"currentAccessories\" type=\"checkbox\" value=\"Other\"/> Other</label></div></div>\n<label class=\"field span-12\">Additional current seating / accessory information<textarea id=\"currentSeatingInfo\"></textarea></label>\n</div>\n</div>\n</section>\n<section class=\"card section\" id=\"section3\">\n<div class=\"section-header\"><h2>Section 3: Functional assessment, seated posture and MAT</h2><p>Records what the client can do, how they sit now, what is reducible, and what the proposed posture needs to accommodate or support.</p><button class=\"section-toggle\" onclick=\"toggleSection('section3', this)\" type=\"button\">Minimise</button></div>\n<div class=\"section-body\">\n<div class=\"subhead\">Current seated position</div>\n<div class=\"grid compact\">\n<div class=\"span-4\"><strong>Pelvis - sagittal plane</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"pelvisSag\" type=\"radio\" value=\"Neutral\"/> Neutral</label><label class=\"radio\"><input name=\"pelvisSag\" type=\"radio\" value=\"Posterior pelvic tilt\"/> Posterior pelvic tilt</label><label class=\"radio\"><input name=\"pelvisSag\" type=\"radio\" value=\"Anterior pelvic tilt\"/> Anterior pelvic tilt</label></div></div>\n<div class=\"span-4\"><strong>Pelvis - frontal plane</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"pelvisFront\" type=\"radio\" value=\"Neutral\"/> Neutral</label><label class=\"radio\"><input name=\"pelvisFront\" type=\"radio\" value=\"Right obliquity\"/> Right obliquity</label><label class=\"radio\"><input name=\"pelvisFront\" type=\"radio\" value=\"Left obliquity\"/> Left obliquity</label></div></div>\n<div class=\"span-4\"><strong>Pelvis - transverse plane</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"pelvisTrans\" type=\"radio\" value=\"Neutral\"/> Neutral</label><label class=\"radio\"><input name=\"pelvisTrans\" type=\"radio\" value=\"Right rotation\"/> Right rotation</label><label class=\"radio\"><input name=\"pelvisTrans\" type=\"radio\" value=\"Left rotation\"/> Left rotation</label></div></div>\n<label class=\"field span-12\">Pelvis additional information<textarea id=\"pelvisNotes\"></textarea></label>\n<div class=\"span-6\"><strong>Lower extremities</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Hip neutral\"/> Hip neutral</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Hip abducted R\"/> Hip abducted R</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Hip abducted L\"/> Hip abducted L</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Hip adducted R\"/> Hip adducted R</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Hip adducted L\"/> Hip adducted L</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Externally rotated R\"/> Externally rotated R</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Externally rotated L\"/> Externally rotated L</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Internally rotated R\"/> Internally rotated R</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Internally rotated L\"/> Internally rotated L</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Wind sweeping R\"/> Wind sweeping R</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Wind sweeping L\"/> Wind sweeping L</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Foot eversion\"/> Foot eversion</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Foot inversion\"/> Foot inversion</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Plantarflexed\"/> Plantarflexed</label><label class=\"check\"><input name=\"lowerExt\" type=\"checkbox\" value=\"Dorsiflexed\"/> Dorsiflexed</label></div></div>\n<div class=\"span-6\"><strong>Spine / cervical / shoulders</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Scoliosis convex right\"/> Scoliosis convex right</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Scoliosis convex left\"/> Scoliosis convex left</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Thoracic kyphosis\"/> Thoracic kyphosis</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Lumbar lordosis\"/> Lumbar lordosis</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Spinal rotation R\"/> Spinal rotation R</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Spinal rotation L\"/> Spinal rotation L</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Cervical flexed\"/> Cervical flexed</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Cervical extended\"/> Cervical extended</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Cervical lateral flexion L\"/> Cervical lateral flexion L</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Cervical lateral flexion R\"/> Cervical lateral flexion R</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Cervical rotation L\"/> Cervical rotation L</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Cervical rotation R\"/> Cervical rotation R</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Shoulder protracted L\"/> Shoulder protracted L</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Shoulder protracted R\"/> Shoulder protracted R</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Shoulder low L\"/> Shoulder low L</label><label class=\"check\"><input name=\"spineCervical\" type=\"checkbox\" value=\"Shoulder low R\"/> Shoulder low R</label></div></div>\n<label class=\"field span-12\">Posture and functional impact notes<textarea id=\"postureImpactNotes\" placeholder=\"Describe pain, respiration, vision, reaching, balance, transfers, propulsion, care access and tolerance.\"></textarea></label>\n</div>\n<div class=\"subhead\">Functional activities</div>\n<table class=\"activity-table\">\n<thead><tr><th>Activity</th><th>Level</th><th>Notes / barriers / equipment implications</th></tr></thead>\n<tbody>\n<tr><td>Eating</td><td><select id=\"act_0\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_0\" type=\"text\"/></td></tr><tr><td>Grooming</td><td><select id=\"act_1\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_1\" type=\"text\"/></td></tr><tr><td>Bathing</td><td><select id=\"act_2\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_2\" type=\"text\"/></td></tr><tr><td>Dressing - upper body</td><td><select id=\"act_3\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_3\" type=\"text\"/></td></tr><tr><td>Dressing - lower body</td><td><select id=\"act_4\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_4\" type=\"text\"/></td></tr><tr><td>Toileting</td><td><select id=\"act_5\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_5\" type=\"text\"/></td></tr><tr><td>Bed/chair/wheelchair transfer</td><td><select id=\"act_6\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_6\" type=\"text\"/></td></tr><tr><td>Toilet transfer</td><td><select id=\"act_7\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_7\" type=\"text\"/></td></tr><tr><td>Shower/bath transfer</td><td><select id=\"act_8\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_8\" type=\"text\"/></td></tr><tr><td>Propel</td><td><select id=\"act_9\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_9\" type=\"text\"/></td></tr><tr><td>Reposition / pressure relieve</td><td><select id=\"act_10\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_10\" type=\"text\"/></td></tr><tr><td>Reach / pick up objects</td><td><select id=\"act_11\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_11\" type=\"text\"/></td></tr><tr><td>Navigate tight spaces</td><td><select id=\"act_12\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_12\" type=\"text\"/></td></tr><tr><td>Manage ramps / inclines / curbs</td><td><select id=\"act_13\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_13\" type=\"text\"/></td></tr><tr><td>Cross streets / community safety</td><td><select id=\"act_14\"><option></option><option>Independent</option><option>Partial assistance</option><option>Dependent</option><option>Not applicable</option></select></td><td><input id=\"actNote_14\" type=\"text\"/></td></tr>\n</tbody>\n</table>\n<div class=\"subhead\">Home, community and transport environment</div>\n<div class=\"grid compact\">\n<div class=\"span-4\"><strong>Household</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"household\" type=\"radio\" value=\"Lives alone\"/> Lives alone</label><label class=\"radio\"><input name=\"household\" type=\"radio\" value=\"Lives with others\"/> Lives with others</label></div></div>\n<div class=\"span-4\"><strong>Support</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"support\" type=\"radio\" value=\"Independent\"/> Independent</label><label class=\"radio\"><input name=\"support\" type=\"radio\" value=\"Family support\"/> Family support</label><label class=\"radio\"><input name=\"support\" type=\"radio\" value=\"Carer support\"/> Carer support</label></div></div>\n<label class=\"field span-4\">Formal support hours/package<input id=\"formalSupport\" type=\"text\"/></label>\n<label class=\"field span-3\">Door widths<span class=\"hint\">Record measured clear opening in mm. Measure the actual clear opening, not just the door leaf. Compare against the proposed overall wheelchair width, approach angle and turning space.</span><input id=\"doorWidths\" placeholder=\"e.g. bedroom 820 mm, bathroom 760 mm - measure clear opening\" type=\"text\"/></label>\n<label class=\"field span-3\">Threshold heights<input id=\"thresholds\" type=\"text\"/></label>\n<label class=\"field span-3\">Turning circles<input id=\"turningCircles\" type=\"text\"/></label>\n<label class=\"field span-3\">Bed/chair heights<input id=\"surfaceHeights\" type=\"text\"/></label>\n<div class=\"span-6\"><strong>Internal surfaces</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"internalSurfaces\" type=\"checkbox\" value=\"Tiles/vinyl/wood\"/> Tiles/vinyl/wood</label><label class=\"check\"><input name=\"internalSurfaces\" type=\"checkbox\" value=\"Carpet/rugs\"/> Carpet/rugs</label><label class=\"check\"><input name=\"internalSurfaces\" type=\"checkbox\" value=\"Tight spaces\"/> Tight spaces</label><label class=\"check\"><input name=\"internalSurfaces\" type=\"checkbox\" value=\"Narrow doors\"/> Narrow doors</label></div></div>\n<div class=\"span-6\"><strong>External terrain</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Concrete/paver/tile\"/> Concrete/paver/tile</label><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Gravel/dirt\"/> Gravel/dirt</label><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Grass/soft ground\"/> Grass/soft ground</label><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Uneven terrain\"/> Uneven terrain</label><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Hills\"/> Hills</label><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Steep ramps\"/> Steep ramps</label><label class=\"check\"><input name=\"externalTerrain\" type=\"checkbox\" value=\"Curbs\"/> Curbs</label></div></div>\n<label class=\"field span-4\">Steepest ramp / slope<input id=\"steepestSlope\" placeholder=\"degrees, ratio or description\" type=\"text\"/></label>\n<label class=\"field span-8\">Local community environment<textarea id=\"communityEnvironment\" placeholder=\"School/work, footpaths, shopping centres, hospital, public transport, rural property, distance demands.\"></textarea></label>\n<div class=\"span-6\"><strong>Transport type</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"transport\" type=\"checkbox\" value=\"Modified vehicle\"/> Modified vehicle</label><label class=\"check\"><input name=\"transport\" type=\"checkbox\" value=\"Standard vehicle\"/> Standard vehicle</label><label class=\"check\"><input name=\"transport\" type=\"checkbox\" value=\"Taxi\"/> Taxi</label><label class=\"check\"><input name=\"transport\" type=\"checkbox\" value=\"Bus\"/> Bus</label><label class=\"check\"><input name=\"transport\" type=\"checkbox\" value=\"Train\"/> Train</label><label class=\"check\"><input name=\"transport\" type=\"checkbox\" value=\"Other\"/> Other</label></div></div>\n<div class=\"span-6\"><strong>Travel position</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"travelPosition\" type=\"radio\" value=\"In wheelchair\"/> In wheelchair</label><label class=\"radio\"><input name=\"travelPosition\" type=\"radio\" value=\"In vehicle seat\"/> In vehicle seat</label><label class=\"radio\"><input name=\"travelPosition\" type=\"radio\" value=\"Further assessment required\"/> Further assessment required</label></div></div>\n<label class=\"field span-12\">Transport details<textarea id=\"transportDetails\" placeholder=\"Vehicle model, wheelchair restraint system, transfer method, boot/storage dimensions, carer handling.\"></textarea></label>\n</div>\n<div class=\"subhead\">Supine MAT evaluation and sitting balance</div>\n<div class=\"grid compact mat-grid\">\n<div class=\"span-3\"><strong>Completed on plinth</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"matCompleted\" type=\"radio\" value=\"Yes\"/> Yes</label><label class=\"radio\"><input name=\"matCompleted\" type=\"radio\" value=\"No\"/> No</label></div></div>\n<div class=\"span-3\"><strong>Pelvic tilt</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"supinePelvicTilt\" type=\"radio\" value=\"NAD\"/> NAD</label><label class=\"radio\"><input name=\"supinePelvicTilt\" type=\"radio\" value=\"Anterior pelvic tilt\"/> Anterior</label><label class=\"radio\"><input name=\"supinePelvicTilt\" type=\"radio\" value=\"Posterior pelvic tilt\"/> Posterior</label></div></div>\n<div class=\"span-3\"><strong>Pelvic tilt flexibility</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"tiltFlex\" type=\"radio\" value=\"Reducible\"/> Reducible</label><label class=\"radio\"><input name=\"tiltFlex\" type=\"radio\" value=\"Non-reducible\"/> Non-reducible</label></div></div>\n<div class=\"span-3\"><strong>Sitting balance</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"sittingBalance\" type=\"radio\" value=\"Independent sitting\"/> Independent</label><label class=\"radio\"><input name=\"sittingBalance\" type=\"radio\" value=\"Sitting with propping\"/> Propping</label><label class=\"radio\"><input name=\"sittingBalance\" type=\"radio\" value=\"Unable to sit without support\"/> Unable</label></div></div>\n<div class=\"span-4\"><strong>Pelvic rotation</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"supineRotation\" type=\"radio\" value=\"NAD\"/> NAD</label><label class=\"radio\"><input name=\"supineRotation\" type=\"radio\" value=\"Right rotation\"/> Right</label><label class=\"radio\"><input name=\"supineRotation\" type=\"radio\" value=\"Left rotation\"/> Left</label><label class=\"radio\"><input name=\"rotationFlex\" type=\"radio\" value=\"Reducible\"/> Reducible</label><label class=\"radio\"><input name=\"rotationFlex\" type=\"radio\" value=\"Non-reducible\"/> Non-reducible</label></div></div>\n<div class=\"span-4\"><strong>Pelvic obliquity</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"supineObliquity\" type=\"radio\" value=\"NAD\"/> NAD</label><label class=\"radio\"><input name=\"supineObliquity\" type=\"radio\" value=\"Right obliquity\"/> Right</label><label class=\"radio\"><input name=\"supineObliquity\" type=\"radio\" value=\"Left obliquity\"/> Left</label><label class=\"radio\"><input name=\"obliquityFlex\" type=\"radio\" value=\"Reducible\"/> Reducible</label><label class=\"radio\"><input name=\"obliquityFlex\" type=\"radio\" value=\"Non-reducible\"/> Non-reducible</label></div></div>\n<div class=\"span-4\"><strong>Tone / movement</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"toneMovement\" type=\"checkbox\" value=\"Hypertonic\"/> Hypertonic</label><label class=\"check\"><input name=\"toneMovement\" type=\"checkbox\" value=\"Hypotonic\"/> Hypotonic</label><label class=\"check\"><input name=\"toneMovement\" type=\"checkbox\" value=\"Mixed tone\"/> Mixed tone</label><label class=\"check\"><input name=\"toneMovement\" type=\"checkbox\" value=\"Ataxia\"/> Ataxia</label><label class=\"check\"><input name=\"toneMovement\" type=\"checkbox\" value=\"Athetosis\"/> Athetosis</label><label class=\"check\"><input name=\"toneMovement\" type=\"checkbox\" value=\"Spasm/reflex triggers\"/> Spasm/reflex triggers</label></div></div>\n<label class=\"field span-6\">ROM limits / joint flexibility notes<textarea id=\"romNotes\" placeholder=\"Hip flexion, abduction/adduction, rotation, knee extension, feet, pain limits. Do not simulate beyond available range.\"></textarea></label>\n<label class=\"field span-6\">Simulation findings and proposed posture<textarea id=\"simulationFindings\" placeholder=\"What changed when posture was supported? What position improves function, pressure management, gaze, comfort and care access?\"></textarea></label>\n</div>\n</div>\n</section>\n<section class=\"card section\" id=\"section4\">\n<div class=\"section-header\"><h2>Section 4: Proposed product parameters</h2><p>This is the supplier-facing prescription frame. Complete as a proposed trial direction first; finalise after trial, fitting and review.</p><button class=\"section-toggle\" onclick=\"toggleSection('section4', this)\" type=\"button\">Minimise</button></div>\n<div class=\"section-body\">\n<div class=\"subhead\">Base direction and trial class</div>\n<div class=\"grid compact\">\n<div class=\"span-8\"><strong>Likely prescription pathway</strong><div class=\"check-grid two\"><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Basic manual / transit\"/> Basic manual / transit</label><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Highly adjustable manual\"/> Highly adjustable manual</label><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Scripted/custom manual\"/> Scripted/custom manual</label><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Manual tilt-in-space\"/> Manual tilt-in-space</label><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Power wheelchair\"/> Power wheelchair</label><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Manual chair plus power assist\"/> Manual chair plus power assist</label><label class=\"radio\"><input name=\"proposedPathway\" type=\"radio\" value=\"Further specialist assessment before product direction\"/> Further specialist assessment before product direction</label></div></div>\n<label class=\"field span-4\">Preferred / likely suppliers to contact<input id=\"supplierPreference\" placeholder=\"Primary supplier, custom seating supplier, power mobility supplier, local repair provider, other\" type=\"text\"/></label>\n<label class=\"field span-12\">Reason for base direction<textarea id=\"baseDirectionReason\" placeholder=\"Link equipment direction to goals, function, environment, postural support, pressure management, transport and funding.\"></textarea></label>\n</div>\n<div class=\"subhead\">Key seating dimensions and seating system</div>\n<div class=\"note\" style=\"margin-bottom:12px;\">\n            Auto-calculated values are <strong>starting points only</strong>, based on Section 2 measurements and simple prescription rules. Overwrite any field where MAT findings, posture, pressure care, transfers, propulsion, supplier measurement conventions or trial outcomes indicate a better fit. Manually edited fields will not be overwritten unless you choose to re-apply calculations.\n            <div style=\"margin-top:10px;\"><button class=\"btn\" onclick=\"reapplyAutoCalculations()\" type=\"button\">Re-apply auto-calculations</button></div>\n</div>\n<div class=\"grid compact\">\n<div class=\"dimension-grid span-12\">\n<label class=\"field\">Required seat width mm<input id=\"reqSeatWidth\" min=\"0\" step=\"1\" type=\"number\"/><div class=\"guidance-line\" id=\"guide_reqSeatWidth\"></div></label><label class=\"field\">Estimated / proposed overall wheelchair width mm<input id=\"proposedOverallWidth\" min=\"0\" placeholder=\"Auto-estimates seat width + 200 mm; overwrite with supplier total width\" step=\"1\" type=\"number\"/><div class=\"guidance-line\" id=\"guide_proposedOverallWidth\"></div></label>\n<label class=\"field\">Required seat depth mm<input id=\"reqSeatDepth\" min=\"0\" step=\"1\" type=\"number\"/><div class=\"guidance-line\" id=\"guide_reqSeatDepth\"></div></label>\n<label class=\"field\">Required front seat height mm<input id=\"reqSeatHeight\" min=\"0\" step=\"1\" type=\"number\"/><div class=\"guidance-line\" id=\"guide_reqSeatHeight\"></div></label>\n<label class=\"field\">Required backrest height<textarea id=\"reqBackHeight\" placeholder=\"e.g. 400 mm to inferior scapula, or shoulder/head level where clinically indicated.\"></textarea><div class=\"guidance-line\" id=\"guide_reqBackHeight\"></div></label>\n<label class=\"field\">Cushion profile<select id=\"cushionProfile\"><option></option><option>Low profile 1-2 inch</option><option>High profile 3 inch +</option></select><div class=\"guidance-line\" id=\"guide_cushionProfile\"></div></label>\n<label class=\"field\">Head support<select id=\"headSupport\"><option></option><option>Yes</option><option>No</option></select><div class=\"guidance-line\" id=\"guide_headSupport\"></div></label>\n<label class=\"field\">Cushion recommendation<textarea id=\"proposedCushion\" placeholder=\"Describe cushion type, contour, pressure rationale, transfer impact and skin follow-up.\"></textarea><div class=\"guidance-line\" id=\"guide_proposedCushion\"></div></label>\n<label class=\"field\">Backrest recommendation<textarea id=\"proposedBackrest\" placeholder=\"Describe backrest style, height, contour, laterals and correction/accommodation rationale.\"></textarea><div class=\"guidance-line\" id=\"guide_proposedBackrest\"></div></label>\n<label class=\"field\">Seat angle / tilt<textarea id=\"seatAngleTilt\" placeholder=\"Describe fixed seat angle, tilt-in-space, anterior tilt, pressure/posture rationale and transfer impact.\"></textarea><div class=\"guidance-line\" id=\"guide_seatAngleTilt\"></div></label>\n<label class=\"field\">Backrest recline<textarea id=\"backrestRecline\" placeholder=\"Describe recline angle/function, care/rest rationale, shear/sliding considerations and belt position.\"></textarea><div class=\"guidance-line\" id=\"guide_backrestRecline\"></div></label>\n<label class=\"field\">Legrest angle / support<textarea id=\"legrestAngle\" placeholder=\"Describe hanger/legrest angle, footplate setup, calf/heel support, ROM and swelling/tone considerations.\"></textarea><div class=\"guidance-line\" id=\"guide_legrestAngle\"></div></label>\n<label class=\"field\">Arm support<textarea id=\"armSupport\" placeholder=\"Describe armrest/arm trough height, length, padding, swing-away/flip-back needs and transfer/reach impact.\"></textarea><div class=\"guidance-line\" id=\"guide_armSupport\"></div></label>\n</div>\n<div class=\"span-12\"><strong>Postural supports</strong><div class=\"check-grid four\"><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Pre-ischial contour / ridge\"/> Pre-ischial contour / ridge</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Cushion build-up\"/> Cushion build-up</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Cushion wedge\"/> Cushion wedge</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Thigh guide\"/> Thigh guide</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Pommel\"/> Pommel</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Lateral supports\"/> Lateral supports</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Deep contour backrest\"/> Deep contour backrest</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Lumbar support\"/> Lumbar support</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Pelvic pad PSIS-level\"/> Pelvic pad PSIS-level</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Tray\"/> Tray</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Footrest build-up\"/> Footrest build-up</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Angle adjustable footrest / wedge\"/> Angle adjustable footrest / wedge</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Calf strap\"/> Calf strap</label><label class=\"check\"><input name=\"posturalSupports\" type=\"checkbox\" value=\"Heel strap\"/> Heel strap</label></div></div>\n<div class=\"span-12\"><strong>Belts / secondary supports</strong><div class=\"check-grid four\"><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Pelvic belt\"/> Pelvic belt</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Four-point pelvic belt\"/> Four-point pelvic belt</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Chest belt\"/> Chest belt</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Shoulder harness\"/> Shoulder harness</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Calf strap\"/> Calf strap</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Ankle huggers\"/> Ankle huggers</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Foot box\"/> Foot box</label><label class=\"check\"><input name=\"beltsSupports\" type=\"checkbox\" value=\"Head strap\"/> Head strap</label></div></div>\n<label class=\"field span-12\">Postural support descriptors / mounting notes<textarea id=\"posturalSupportDescriptors\"></textarea></label>\n</div>\n<div class=\"subhead\">Manual wheelchair parameters</div>\n<div class=\"grid compact\"><div class=\"note span-12 manual-source-note\" id=\"manualSourceSummary\">Manual type and frame are not repeated here. Use the prescription pathway above and manual chair selection in Section 2, then record any proposed frame/configuration changes in the notes below.</div>\n<div class=\"span-4\"><strong>Frame material</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"frameMaterial\" type=\"checkbox\" value=\"Aluminium\"/> Aluminium</label><label class=\"check\"><input name=\"frameMaterial\" type=\"checkbox\" value=\"Steel\"/> Steel</label><label class=\"check\"><input name=\"frameMaterial\" type=\"checkbox\" value=\"Carbon fibre\"/> Carbon fibre</label><label class=\"check\"><input name=\"frameMaterial\" type=\"checkbox\" value=\"Titanium\"/> Titanium</label></div></div>\n<div class=\"span-6\"><strong>Wheels / drive</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Attendant/transit\"/> Attendant/transit</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Large rear wheel\"/> Large rear wheel</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"One arm drive - level\"/> One arm drive - level</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"One arm drive - through axle\"/> One arm drive - through axle</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Solid tyres\"/> Solid tyres</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Pneumatic tyres\"/> Pneumatic tyres</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"High tread tyres\"/> High tread tyres</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Spoke wheels\"/> Spoke wheels</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Mag wheels\"/> Mag wheels</label><label class=\"check\"><input name=\"manualWheels\" type=\"checkbox\" value=\"Spoke guard\"/> Spoke guard</label></div></div>\n<div class=\"span-6\"><strong>Manual accessories</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Wheel camber\"/> Wheel camber</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Aluminium rims\"/> Aluminium rims</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Plastic rims\"/> Plastic rims</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"High friction rims\"/> High friction rims</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Ergonomic rims\"/> Ergonomic rims</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Castors &lt;6 inch\"/> Castors &lt;6 inch</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Castors 6 inch\"/> Castors 6 inch</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Castors 8 inch\"/> Castors 8 inch</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Castors &gt;8 inch\"/> Castors &gt;8 inch</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Brake extensions\"/> Brake extensions</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Scissor brakes\"/> Scissor brakes</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Attendant drum brakes\"/> Attendant drum brakes</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Anti-tips\"/> Anti-tips</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Tip-assist\"/> Tip-assist</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Extended push handles\"/> Extended push handles</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Stroller handles\"/> Stroller handles</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Lightweight\"/> Lightweight</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Foldable\"/> Foldable</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Dismantleable\"/> Dismantleable</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Robust\"/> Robust</label><label class=\"check\"><input name=\"manualAccessories\" type=\"checkbox\" value=\"Power assist required\"/> Power assist required</label></div></div>\n<label class=\"field span-12\">Manual wheelchair configuration notes<textarea id=\"manualConfigNotes\" placeholder=\"Rear axle position, centre of gravity, seat-to-floor height, foot propulsion needs, shoulder preservation, carer handling, transport/storage.\"></textarea></label>\n</div>\n<div class=\"subhead\">Power wheelchair parameters</div>\n<div class=\"grid compact\">\n<div class=\"span-4\"><strong>Drive configuration to trial</strong><div class=\"check-grid\"><label class=\"radio\"><input name=\"proposedDrive\" type=\"radio\" value=\"Front wheel drive\"/> Front wheel drive</label><label class=\"radio\"><input name=\"proposedDrive\" type=\"radio\" value=\"Mid wheel drive\"/> Mid wheel drive</label><label class=\"radio\"><input name=\"proposedDrive\" type=\"radio\" value=\"Rear wheel drive\"/> Rear wheel drive</label><label class=\"radio\"><input name=\"proposedDrive\" type=\"radio\" value=\"To trial / compare\"/> To trial / compare</label></div></div>\n<div class=\"span-8\"><strong>Power seat functions requested for trial</strong><div class=\"check-grid four\"><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Power tilt\"/> Power tilt</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Power recline\"/> Power recline</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Power elevating legrests\"/> Power elevating legrests</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Seat elevate\"/> Seat elevate</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Anterior tilt\"/> Anterior tilt</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Active reach\"/> Active reach</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Standing\"/> Standing</label><label class=\"check\"><input name=\"proposedSeatFunctions\" type=\"checkbox\" value=\"Manual recline/ELR only\"/> Manual recline/ELR only</label></div></div>\n<label class=\"field span-4\">Controls<input id=\"powerControls\" placeholder=\"Joystick, attendant control, alternate drive control, tray mount, swing-away\" type=\"text\"/></label>\n<label class=\"field span-4\">Power base / seating notes<input id=\"powerBaseNotes\" type=\"text\"/></label>\n<label class=\"field span-4\">Battery/charging/storage considerations<input id=\"powerChargingNotes\" type=\"text\"/></label>\n</div>\n</div>\n</section>\n<section class=\"card section\" id=\"section5\">\n<div class=\"section-header\"><h2>Section 5: Trial plan, supplier handover, fitting and training</h2><p>Turns assessment findings into a practical trial and quote request, then captures what must be checked at delivery.</p><button class=\"section-toggle\" onclick=\"toggleSection('section5', this)\" type=\"button\">Minimise</button></div>\n<div class=\"section-body\">\n<div class=\"subhead\">Trial and quote request</div>\n<div class=\"grid compact\">\n<div class=\"span-12\"><strong>Suppliers to consider</strong><div class=\"check-grid four\"><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Primary wheelchair supplier\"/> Primary wheelchair supplier</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Custom seating supplier\"/> Custom seating supplier</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Power mobility supplier\"/> Power mobility supplier</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Manual wheelchair supplier\"/> Manual wheelchair supplier</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Local service/repair provider\"/> Local service/repair provider</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Other supplier\"/> Other supplier</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Specialist custom fabrication\"/> Specialist custom fabrication</label><label class=\"check\"><input name=\"suppliers\" type=\"checkbox\" value=\"Engineering / technical input\"/> Engineering / technical input</label></div></div>\n<div class=\"span-6\"><strong>Trial completed / planned location</strong><div class=\"check-grid two\"><label class=\"check\"><input name=\"trialLocations\" type=\"checkbox\" value=\"Hospital\"/> Hospital</label><label class=\"check\"><input name=\"trialLocations\" type=\"checkbox\" value=\"Home\"/> Home</label><label class=\"check\"><input name=\"trialLocations\" type=\"checkbox\" value=\"Showroom\"/> Showroom</label><label class=\"check\"><input name=\"trialLocations\" type=\"checkbox\" value=\"Community\"/> Community</label><label class=\"check\"><input name=\"trialLocations\" type=\"checkbox\" value=\"Vehicle/transport\"/> Vehicle/transport</label><label class=\"check\"><input name=\"trialLocations\" type=\"checkbox\" value=\"Work/school\"/> Work/school</label></div></div>\n<label class=\"field span-6\">Potential trial equipment to meet goals and needs<textarea id=\"trialEquipment\" placeholder=\"List product classes/models, alternatives and features that must be trialled.\"></textarea></label>\n<label class=\"field span-6\">Products trialled / outcomes<textarea id=\"productsTrialled\"></textarea></label>\n<label class=\"field span-6\">Selected wheelchair, seating and accessories<textarea id=\"selectedEquipment\"></textarea></label>\n<label class=\"field span-12\">Supplier quote instructions<textarea id=\"quoteInstructions\" placeholder=\"Request itemised quote with base, seating, cushion, accessories, mounting hardware, delivery/setup, training, freight, warranty, maintenance/repair pathway and expected lead time.\"></textarea></label>\n</div>\n<div class=\"subhead\">Fitting, training and follow-up checklist</div>\n<div class=\"grid compact\">\n<div class=\"span-12\"><div class=\"check-grid four\"><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Product review after delivery/setup\"/> Product review after delivery/setup</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Propulsion training\"/> Propulsion training</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Navigating tight spaces\"/> Navigating tight spaces</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Doors and thresholds\"/> Doors and thresholds</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Curbs\"/> Curbs</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Ramps/inclines\"/> Ramps/inclines</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Wheelie/manual wheelchair skill\"/> Wheelie/manual wheelchair skill</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Pressure relieving routine\"/> Pressure relieving routine</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Repositioning in chair\"/> Repositioning in chair</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Folding/dismantling/transport\"/> Folding/dismantling/transport</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Power mobility controls and safe use\"/> Power mobility controls and safe use</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Charging and storage routine\"/> Charging and storage routine</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Manual freewheel / motor disengagement\"/> Manual freewheel / motor disengagement</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Cleaning\"/> Cleaning</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Device inspection/common issues\"/> Device inspection/common issues</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Backup plans for breakdown\"/> Backup plans for breakdown</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Maintenance/repair process\"/> Maintenance/repair process</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Replacement schedule - device/seating\"/> Replacement schedule - device/seating</label><label class=\"check\"><input name=\"trainingChecklist\" type=\"checkbox\" value=\"Caregiver training\"/> Caregiver training</label></div></div>\n<label class=\"field span-12\">Training / follow-up notes<textarea id=\"trainingNotes\"></textarea></label>\n</div>\n<div class=\"subhead\">Final supplier handover comments</div>\n<div class=\"grid compact\">\n<label class=\"field span-4\">Identified barriers to goals<textarea id=\"barriersToGoals\"></textarea></label>\n<label class=\"field span-4\">Identified postural / mobility issues<textarea id=\"identifiedIssues\"></textarea></label>\n<label class=\"field span-4\">Potential product parameters summary<textarea id=\"productParametersSummary\"></textarea></label>\n</div>\n<div class=\"note\" style=\"margin-top:14px;\">Supplier output is generated from the fields above. It deliberately leaves live clinical guidance out of the copied brief, while retaining risk flags and trial requirements relevant to supplier shortlisting.</div>\n</div>\n</section>\n</form>\n<aside class=\"sidebar\">\n<div class=\"side-card\">\n<h3>Live clinical reasoning guidance</h3>\n<div class=\"side-body\" id=\"guidanceOutput\"></div>\n</div>\n<div class=\"side-card\">\n<h3>Supplier brief preview</h3>\n<div class=\"side-body\">\n<div class=\"brief-preview\" id=\"supplierBrief\"></div>\n<div class=\"footer-note\">Use “Copy supplier brief” for email handover or “Print supplier brief” for PDF/printing.</div>\n</div>\n</div>\n<div class=\"side-card\">\n<h3>Reference basis</h3>\n<div class=\"side-body\" style=\"font-size:13px;color:#3b4b5d;\">\n<ul class=\"links-list\">\n<li><a href=\"https://www.who.int/publications/i/item/9789240074521\" rel=\"noreferrer\" target=\"_blank\">WHO Wheelchair provision guidelines, 2023</a></li>\n<li><a href=\"https://www.ncbi.nlm.nih.gov/books/NBK143782/\" rel=\"noreferrer\" target=\"_blank\">WHO manual wheelchair guideline definition of appropriate wheelchair</a></li>\n<li><a href=\"https://www.resna.org/Resources/Position-Papers-and-Service-Provision-Guidelines\" rel=\"noreferrer\" target=\"_blank\">RESNA service provision framework</a></li>\n\n<li><a href=\"https://wheelchairskillsprogram.ca/\" rel=\"noreferrer\" target=\"_blank\">Wheelchair Skills Program</a></li>\n\n</ul>\n<div class=\"footer-note\">Use these as the guidance basis only. The tool still requires clinical judgement, trial confirmation, supplier specification checks and local funding review.</div>\n</div>\n</div>\n</aside>"

